@js:
try{
let all = [];
let 展开符 = "↓";
let 收起符 = "↑";
let rssData = JSON.parse(String(source.getVariable()) || "{}");

//一行个数
let num = 3;
let d = {
    1: 1,
    2: 0.4,
    3: 0.25,
    4: 0.2,
    5: 0.15,
    7: 0.1,
    10: 0.05
};

let push = (title, url, num, g,action) =>{
    num = Number(num ?? 3);
    if(num!=0){
        num = num<1?num:d[num];
    }
	let j = {
    title: title,
    url: url,
    style: {
        layout_flexGrow: g == 0 ? g : 1,
        layout_flexBasisPercent: num                           
    }
  }
  if(num===0){
      delete j.style.layout_flexBasisPercent
  }
     if(action){
         j.action = action.action;
         j.name = action.name;
         j.type = action.type;
         j.chars = action.chars;
         j.viewName = action.viewName;
         j.default = action.default;      
         j.style.layout_justifySelf = action.style;
         j.style.layout_wrapBefore = action.wrap;
     }  
     all.push(j)	
} 

let rssUrl = infoMap["rssUrl"];


push("订阅源管理器","",1,1,{
    type:"button",
    action:`checkRss()`
});

push("url","",0.7,1,{
    type:"text",
    viewName:"'网络导入链接'",
    action:"java.refreshExplore();",
    default: ""
});

push("导入","",0.2,1,{
    type:"button",
    action:`getSource("${infoMap['url']}");`
});

push("rssUrl","",0.7,1,{
    type:"text",
    viewName:"'请打开web服务，输入web服务地址'",
    default:rssData.rssUrl ?? ""
});

push("ok","",0.2,1,{
    type:"button",
    viewName:"'拉取'",
    action:`getRssSource("${rssUrl}");`
});

let groups = rssData.groups ?? [];
let webs = rssData.webs ?? [];
groups.forEach(x=>{
    push("📁"+x.name,"",1,1,{
        "type": "toggle",
        "chars": [展开符, 收起符],
        "action":"source.refreshExplore();java.refreshExplore();",
        "default": infoMap["📁"+x.name] || 展开符
     });

     let findwebs = webs.filter(web => 
    web.group?.some(item => item === x.id)
);


if(String(infoMap["📁"+x.name]) === 展开符 || !infoMap["📁"+x.name]){
     if(x.id==="-2")findwebs=webs;
     findwebs.forEach(web=>{
         let url = JSON.stringify(web.url);
         if(web.url !== "订阅源管理器"){
             push(web.name.trim(),"",0,1,{
                 type:"button",
                 "action":`java.open("rss",null,null,${url})`
              });
        }
     })
}
});

infoMap.save();
JSON.stringify(all)

}catch(e){
    java.toast("出错")
